import { createHash, randomBytes } from "node:crypto";
import type {
  Clock,
  MembershipRepository,
  PasswordVerifier,
  SessionRepository,
  SessionTokenService,
  UserIdentityRepository,
} from "../../../src/modules/identity/ports/index.js";
import type {
  UserIdentity,
  UserMembership,
  UserSession,
} from "../../../src/modules/identity/identity.types.js";

export class FakeUserIdentityRepository implements UserIdentityRepository {
  private users = new Map<string, UserIdentity>();

  add(user: UserIdentity): void {
    this.users.set(user.id, user);
    this.users.set(user.loginIdentifier, user);
  }

  async findByIdentifier(identifier: string): Promise<UserIdentity | null> {
    return this.users.get(identifier) ?? null;
  }

  async findById(userId: string): Promise<UserIdentity | null> {
    return this.users.get(userId) ?? null;
  }
}

export class FakeMembershipRepository implements MembershipRepository {
  private memberships: UserMembership[] = [];

  add(...memberships: UserMembership[]): void {
    this.memberships.push(...memberships);
  }

  async findActiveMembershipsByUser(
    userId: string,
  ): Promise<readonly UserMembership[]> {
    return this.memberships.filter((m) => m.userId === userId);
  }

  async findByUserAndSchool(
    userId: string,
    schoolId: string,
  ): Promise<UserMembership | null> {
    return (
      this.memberships.find(
        (m) => m.userId === userId && m.schoolId === schoolId,
      ) ?? null
    );
  }
}

export class FakePasswordVerifier implements PasswordVerifier {
  private passwords = new Map<string, string>();
  readonly calls: Array<{ kind: "real" | "dummy"; password: string }> = [];

  register(userId: string, password: string): void {
    this.passwords.set(userId, password);
  }

  async verify(password: string, hash: string): Promise<boolean> {
    this.calls.push({ kind: "real", password });
    // In tests, the "hash" is the userId placeholder recorded by fixtures.
    const expected = this.passwords.get(hash);
    return expected === password;
  }

  async verifyDummy(password: string): Promise<boolean> {
    this.calls.push({ kind: "dummy", password });
    return false;
  }
}

export class FakeSessionTokenService implements SessionTokenService {
  private counter = 0;

  async generatePair(): Promise<{
    accessToken: string;
    refreshToken: string;
  }> {
    this.counter += 1;
    const accessToken = `access-token-${this.counter}-${randomBytes(8).toString("hex")}`;
    const refreshToken = `refresh-token-${this.counter}-${randomBytes(8).toString("hex")}`;
    return { accessToken, refreshToken };
  }

  async hash(token: string): Promise<string> {
    return createHash("sha256").update(token).digest("hex");
  }
}

export class FakeSessionRepository implements SessionRepository {
  private sessionsById = new Map<string, UserSession>();
  private accessIndex = new Map<string, string>();
  private refreshIndex = new Map<string, string>();
  private nextId = 1;
  private failNextRotation = false;

  async create(
    params: Readonly<{
      userId: string;
      activeSchoolId: string | null;
      accessTokenHash: string;
      refreshTokenHash: string;
      accessExpiresAt: Date;
      refreshExpiresAt: Date;
    }>,
  ): Promise<UserSession> {
    const session: UserSession = {
      id: `session-${this.nextId++}`,
      ...params,
      revokedAt: null,
      createdAt: new Date(),
      lastUsedAt: new Date(),
    };
    this.store(session);
    return session;
  }

  async findByAccessTokenHash(
    accessTokenHash: string,
  ): Promise<UserSession | null> {
    const id = this.accessIndex.get(accessTokenHash);
    return id ? (this.sessionsById.get(id) ?? null) : null;
  }

  async findByRefreshTokenHash(
    refreshTokenHash: string,
  ): Promise<UserSession | null> {
    const id = this.refreshIndex.get(refreshTokenHash);
    return id ? (this.sessionsById.get(id) ?? null) : null;
  }

  async revoke(sessionId: string): Promise<void> {
    const session = this.sessionsById.get(sessionId);
    if (session) {
      session.revokedAt = new Date();
    }
  }

  async compareAndRotateRefreshSession(
    params: Readonly<{
      sessionId: string;
      expectedRefreshTokenHash: string;
      now: Date;
      successor: {
        activeSchoolId: string | null;
        accessTokenHash: string;
        refreshTokenHash: string;
        accessExpiresAt: Date;
        refreshExpiresAt: Date;
      };
    }>,
  ): Promise<UserSession | null> {
    const session = this.sessionsById.get(params.sessionId);
    if (
      this.failNextRotation ||
      !session ||
      session.revokedAt ||
      session.refreshTokenHash !== params.expectedRefreshTokenHash ||
      session.refreshExpiresAt <= params.now
    ) {
      this.failNextRotation = false;
      return null;
    }
    session.revokedAt = params.now;
    const successor: UserSession = {
      id: `session-${this.nextId++}`,
      userId: session.userId,
      ...params.successor,
      revokedAt: null,
      createdAt: params.now,
      lastUsedAt: params.now,
    };
    this.store(successor);
    return successor;
  }

  sessionCount(): number {
    return this.sessionsById.size;
  }

  activeSessionCount(): number {
    return [...this.sessionsById.values()].filter(
      (session) => !session.revokedAt,
    ).length;
  }

  failNextCompareAndRotate(): void {
    this.failNextRotation = true;
  }

  private store(session: UserSession): void {
    this.sessionsById.set(session.id, session);
    this.accessIndex.set(session.accessTokenHash, session.id);
    this.refreshIndex.set(session.refreshTokenHash, session.id);
  }
}

export class FakeClock implements Clock {
  constructor(private time = new Date()) {}

  now(): Date {
    return new Date(this.time.getTime());
  }

  advance(ms: number): void {
    this.time = new Date(this.time.getTime() + ms);
  }
}

import type { ExecutionContext } from "@nestjs/common";

export interface MockContextOptions {
  readonly headers?: Record<string, string | string[] | undefined>;
  readonly params?: Record<string, string>;
  readonly query?: Record<string, string>;
  readonly body?: Record<string, unknown>;
}

export function createMockExecutionContext(
  options: MockContextOptions = {},
): ExecutionContext {
  const request = {
    headers: options.headers ?? {},
    params: options.params ?? {},
    query: options.query ?? {},
    body: options.body ?? {},
    method: "GET",
    path: "/test",
  };

  const response = {
    getHeader: (_name: string): string | undefined => "request-id-1",
    setHeader: (_name: string, _value: string): void => {},
  };

  return {
    switchToHttp: () => ({
      getRequest: () => request,
      getResponse: () => response,
    }),
    getHandler: () => () => undefined,
    getClass: () => class TestRef {},
  } as unknown as ExecutionContext;
}

import { HttpStatus, RequestMethod } from "@nestjs/common";
import {
  HTTP_CODE_METADATA,
  METHOD_METADATA,
  PATH_METADATA,
} from "@nestjs/common/constants";
import { validate } from "class-validator";
import { describe, expect, it } from "vitest";
import { LoginDto } from "../../src/modules/identity/dto/login.dto.js";
import { IdentityController } from "../../src/modules/identity/identity.controller.js";
import { IdentityException } from "../../src/modules/identity/identity.errors.js";

function methodMetadata(method: keyof IdentityController) {
  const handler = IdentityController.prototype[method];
  return {
    path: Reflect.getMetadata(PATH_METADATA, handler),
    method: Reflect.getMetadata(METHOD_METADATA, handler),
    status: Reflect.getMetadata(HTTP_CODE_METADATA, handler),
  };
}

describe("IdentityController contract metadata", () => {
  it("keeps the controller at the root", () => {
    expect(Reflect.getMetadata(PATH_METADATA, IdentityController)).toBe("/");
  });

  it.each([
    ["login", "/auth/login", RequestMethod.POST, HttpStatus.OK],
    ["refresh", "/auth/refresh", RequestMethod.POST, HttpStatus.OK],
    ["logout", "/auth/logout", RequestMethod.POST, HttpStatus.NO_CONTENT],
    ["me", "/me", RequestMethod.GET, HttpStatus.OK],
    ["selectSchool", "/auth/select-school", RequestMethod.POST, HttpStatus.OK],
  ] as const)(
    "maps %s to its OpenAPI route and status",
    (method, path, requestMethod, status) => {
      expect(methodMetadata(method)).toEqual({
        path,
        method: requestMethod,
        status,
      });
    },
  );

  it("returns no logout response body", async () => {
    const identityService = {
      logout: async () => undefined,
    };
    const controller = new IdentityController(identityService as never);
    const response = {
      clearCookie: () => response,
    };

    await expect(
      controller.logout(
        {},
        "Bearer access-token",
        undefined,
        response as never,
      ),
    ).resolves.toBeUndefined();
  });

  it("keeps unauthorized errors generic", () => {
    const missing = new IdentityException("AUTH_INVALID_CREDENTIALS");
    const wrongPassword = new IdentityException("AUTH_INVALID_CREDENTIALS");

    expect(missing.getStatus()).toBe(HttpStatus.UNAUTHORIZED);
    expect(missing.getResponse()).toEqual(wrongPassword.getResponse());
    expect(missing.getResponse()).not.toHaveProperty("details.userExists");
  });

  it("rejects invalid login payloads through DTO validation", async () => {
    const dto = Object.assign(new LoginDto(), {
      identifier: "",
      password: "short",
    });

    await expect(validate(dto)).resolves.not.toHaveLength(0);
  });
});

import { describe, expect, it } from "vitest";
import { IdentityException } from "../../src/modules/identity/identity.errors.js";
import {
  MembershipRole,
  MembershipStatus,
  Permission,
  permissionsForPrincipal,
} from "../../src/common/security/index.js";
import { createIdentityServiceFixture } from "./helpers/create-identity-service.js";
import {
  activeStudent,
  activeTeacher,
  inactiveUser,
  invitedMembership,
  leftMembership,
  schoolAdminMembership,
  studentMembership,
  suspendedMembership,
  suspendedTeacher,
  teacherMembership,
} from "./fixtures/users.js";

describe("IdentityService", () => {
  it("performs real password verification for an existing user", async () => {
    const f = createIdentityServiceFixture();
    const user = activeTeacher();
    f.users.add(user);
    f.passwords.register(user.passwordHash, "correct-password");
    f.memberships.add(teacherMembership(user.id));

    await f.service.login(user.loginIdentifier, "correct-password");

    expect(f.passwords.calls).toEqual([
      { kind: "real", password: "correct-password" },
    ]);
  });

  it("performs dummy password verification for a missing user", async () => {
    const f = createIdentityServiceFixture();

    await expect(
      f.service.login("missing@example.edu", "unknown-password"),
    ).rejects.toHaveProperty("code", "AUTH_INVALID_CREDENTIALS");

    expect(f.passwords.calls).toEqual([
      { kind: "dummy", password: "unknown-password" },
    ]);
  });

  it("allows login with correct credentials", async () => {
    const f = createIdentityServiceFixture();
    const user = activeTeacher();
    f.users.add(user);
    f.passwords.register(user.passwordHash, "correct-password");
    f.memberships.add(teacherMembership(user.id));

    const session = await f.service.login(
      user.loginIdentifier,
      "correct-password",
    );

    expect(session.user.id).toBe(user.id);
    expect(session.tokens.accessToken).toBeTruthy();
    expect(session.tokens.refreshToken).toBeTruthy();
  });

  it("returns the same public error for missing account", async () => {
    const f = createIdentityServiceFixture();

    await expect(
      f.service.login("nobody@example.edu", "any-password"),
    ).rejects.toBeInstanceOf(IdentityException);
    await expect(
      f.service.login("nobody@example.edu", "any-password"),
    ).rejects.toHaveProperty("code", "AUTH_INVALID_CREDENTIALS");
  });

  it("returns the same public error for wrong password", async () => {
    const f = createIdentityServiceFixture();
    const user = activeTeacher();
    f.users.add(user);
    f.passwords.register(user.passwordHash, "correct-password");
    f.memberships.add(teacherMembership(user.id));

    await expect(
      f.service.login(user.loginIdentifier, "wrong-password"),
    ).rejects.toBeInstanceOf(IdentityException);
    await expect(
      f.service.login(user.loginIdentifier, "wrong-password"),
    ).rejects.toHaveProperty("code", "AUTH_INVALID_CREDENTIALS");
  });

  it("rejects inactive users", async () => {
    const f = createIdentityServiceFixture();
    const user = inactiveUser();
    f.users.add(user);
    f.passwords.register(user.passwordHash, "password");
    f.memberships.add(teacherMembership(user.id));

    await expect(
      f.service.login(user.loginIdentifier, "password"),
    ).rejects.toHaveProperty("code", "AUTH_INVALID_CREDENTIALS");
  });

  it("rejects invited membership", async () => {
    const f = createIdentityServiceFixture();
    const user = activeTeacher();
    f.users.add(user);
    f.passwords.register(user.passwordHash, "password");
    f.memberships.add(invitedMembership(user.id));

    await expect(
      f.service.login(user.loginIdentifier, "password"),
    ).rejects.toHaveProperty("code", "AUTH_MEMBERSHIP_INACTIVE");
  });

  it("rejects suspended membership", async () => {
    const f = createIdentityServiceFixture();
    const user = suspendedTeacher();
    f.users.add(user);
    f.passwords.register(user.passwordHash, "password");
    f.memberships.add(suspendedMembership(user.id));

    await expect(
      f.service.login(user.loginIdentifier, "password"),
    ).rejects.toHaveProperty("code", "AUTH_MEMBERSHIP_INACTIVE");
  });

  it("rejects left membership", async () => {
    const f = createIdentityServiceFixture();
    const user = activeTeacher();
    f.users.add(user);
    f.passwords.register(user.passwordHash, "password");
    f.memberships.add(leftMembership(user.id));

    await expect(
      f.service.login(user.loginIdentifier, "password"),
    ).rejects.toHaveProperty("code", "AUTH_MEMBERSHIP_INACTIVE");
  });

  it("allows active student membership", async () => {
    const f = createIdentityServiceFixture();
    const user = activeStudent();
    f.users.add(user);
    f.passwords.register(user.passwordHash, "password");
    f.memberships.add(studentMembership(user.id));

    const session = await f.service.login(user.loginIdentifier, "password");

    expect(session.user.id).toBe(user.id);
    expect(session.memberships[0].role).toBe(MembershipRole.STUDENT);
  });

  it("rejects unknown role strings", async () => {
    const f = createIdentityServiceFixture();
    const user = activeTeacher();
    f.users.add(user);
    f.passwords.register(user.passwordHash, "password");
    f.memberships.add({
      id: "membership-unknown",
      userId: user.id,
      schoolId: "school-a",
      schoolName: "示例学校 A",
      role: "SUPER_HACKER" as MembershipRole,
      status: MembershipStatus.ACTIVE,
    });

    await expect(
      f.service.login(user.loginIdentifier, "password"),
    ).rejects.toHaveProperty("code", "AUTH_ROLE_UNSUPPORTED");
  });

  it("accepts the formal RESEARCHER role without granting teaching permissions", async () => {
    const f = createIdentityServiceFixture();
    const user = activeTeacher();
    f.users.add(user);
    f.passwords.register(user.passwordHash, "password");
    f.memberships.add({
      id: "membership-researcher",
      userId: user.id,
      schoolId: "school-a",
      schoolName: "示例学校 A",
      role: "RESEARCHER" as MembershipRole,
      status: MembershipStatus.ACTIVE,
    });

    const session = await f.service.login(user.loginIdentifier, "password");
    const context = await f.service.resolveSession(
      "req-researcher",
      session.tokens.accessToken,
    );

    expect(session.memberships[0]?.role).toBe(MembershipRole.RESEARCHER);
    expect(permissionsForPrincipal(context!.principal)).toEqual([]);
  });

  it("does not use client-declared role", async () => {
    const f = createIdentityServiceFixture();
    const user = activeStudent();
    f.users.add(user);
    f.passwords.register(user.passwordHash, "password");
    f.memberships.add(studentMembership(user.id));

    const session = await f.service.login(user.loginIdentifier, "password");
    expect(session.memberships[0].role).toBe(MembershipRole.STUDENT);
  });

  it("selects the only active school by default", async () => {
    const f = createIdentityServiceFixture();
    const user = activeTeacher();
    f.users.add(user);
    f.passwords.register(user.passwordHash, "password");
    f.memberships.add(teacherMembership(user.id, "school-a"));

    const session = await f.service.login(user.loginIdentifier, "password");
    expect(session.activeSchoolId).toBe("school-a");
  });

  it("selects exactly one active school while ignoring inactive memberships", async () => {
    const f = createIdentityServiceFixture();
    const user = activeTeacher();
    f.users.add(user);
    f.passwords.register(user.passwordHash, "password");
    f.memberships.add(invitedMembership(user.id));
    f.memberships.add(teacherMembership(user.id, "school-b"));

    const session = await f.service.login(user.loginIdentifier, "password");

    expect(session.activeSchoolId).toBe("school-b");
    expect(session.memberships).toHaveLength(1);
  });

  it("leaves activeSchoolId null when multiple schools exist", async () => {
    const f = createIdentityServiceFixture();
    const user = activeTeacher();
    f.users.add(user);
    f.passwords.register(user.passwordHash, "password");
    f.memberships.add(teacherMembership(user.id, "school-a"));
    f.memberships.add(teacherMembership(user.id, "school-b"));

    const session = await f.service.login(user.loginIdentifier, "password");
    expect(session.activeSchoolId).toBeNull();
  });

  it("selects a stable school for a student with multiple invitation memberships", async () => {
    const f = createIdentityServiceFixture();
    const user = activeStudent();
    f.users.add(user);
    f.passwords.register(user.passwordHash, "password");
    f.memberships.add({ ...studentMembership(user.id), id: "membership-student-b", schoolId: "school-b", schoolName: "示例学校 B" });
    f.memberships.add({ ...studentMembership(user.id), id: "membership-student-a", schoolId: "school-a", schoolName: "示例学校 A" });

    const session = await f.service.login(user.loginIdentifier, "password");

    expect(session.activeSchoolId).toBe("school-a");
    await expect(f.service.resolveSession("req-student-multi", session.tokens.accessToken)).resolves.toMatchObject({ tenant: { schoolId: "school-a" } });
  });

  it("does not create a session with zero active memberships", async () => {
    const f = createIdentityServiceFixture();
    const user = activeTeacher();
    f.users.add(user);
    f.passwords.register(user.passwordHash, "password");

    await expect(
      f.service.login(user.loginIdentifier, "password"),
    ).rejects.toHaveProperty("code", "AUTH_MEMBERSHIP_INACTIVE");
    expect(f.sessions.sessionCount()).toBe(0);
  });

  it("does not resolve a tenant for multiple active memberships", async () => {
    const f = createIdentityServiceFixture();
    const user = activeTeacher();
    f.users.add(user);
    f.passwords.register(user.passwordHash, "password");
    f.memberships.add(teacherMembership(user.id, "school-a"));
    f.memberships.add(teacherMembership(user.id, "school-b"));

    const session = await f.service.login(user.loginIdentifier, "password");

    await expect(
      f.service.resolveSession("req-multi", session.tokens.accessToken),
    ).resolves.toBeNull();
    const refreshed = await f.service.refresh(session.tokens.refreshToken);
    expect(refreshed.activeSchoolId).toBeNull();
    await expect(
      f.service.resolveSession("req-refreshed", refreshed.tokens.accessToken),
    ).resolves.toBeNull();
  });

  it("keeps multi-school resolution independent of membership order", async () => {
    for (const schools of [
      ["school-a", "school-b"],
      ["school-b", "school-a"],
    ]) {
      const f = createIdentityServiceFixture();
      const user = activeTeacher();
      f.users.add(user);
      f.passwords.register(user.passwordHash, "password");
      f.memberships.add(
        ...schools.map((school) => teacherMembership(user.id, school)),
      );

      const session = await f.service.login(user.loginIdentifier, "password");
      expect(session.activeSchoolId).toBeNull();
      await expect(
        f.service.resolveSession("req-order", session.tokens.accessToken),
      ).resolves.toBeNull();
    }
  });

  it("builds AuthContext from server-side membership", async () => {
    const f = createIdentityServiceFixture();
    const user = activeTeacher();
    f.users.add(user);
    f.passwords.register(user.passwordHash, "password");
    f.memberships.add(teacherMembership(user.id, "school-a"));

    const session = await f.service.login(user.loginIdentifier, "password");
    const context = await f.service.resolveSession(
      "req-1",
      session.tokens.accessToken,
    );

    expect(context).not.toBeNull();
    expect(context!.principal.userId).toBe(user.id);
    expect(context!.principal.roles).toContain(MembershipRole.TEACHER);
    expect(context!.tenant.schoolId).toBe("school-a");
  });

  it("rejects expired sessions", async () => {
    const f = createIdentityServiceFixture();
    const user = activeTeacher();
    f.users.add(user);
    f.passwords.register(user.passwordHash, "password");
    f.memberships.add(teacherMembership(user.id));

    const session = await f.service.login(user.loginIdentifier, "password");
    f.clock.advance(8 * 24 * 60 * 60 * 1000); // past 7-day refresh TTL

    await expect(
      f.service.refresh(session.tokens.refreshToken),
    ).rejects.toHaveProperty("code", "AUTH_SESSION_EXPIRED");
  });

  it("keeps access valid before its TTL and expires it at the boundary", async () => {
    const start = new Date("2026-07-10T00:00:00.000Z");
    const f = createIdentityServiceFixture(start);
    const user = activeTeacher();
    f.users.add(user);
    f.passwords.register(user.passwordHash, "password");
    f.memberships.add(teacherMembership(user.id));
    const session = await f.service.login(user.loginIdentifier, "password");

    expect(session.tokens.accessExpiresAt).toEqual(
      new Date(start.getTime() + 15 * 60 * 1000),
    );
    expect(session.tokens.refreshExpiresAt).toEqual(
      new Date(start.getTime() + 7 * 24 * 60 * 60 * 1000),
    );

    f.clock.advance(15 * 60 * 1000 - 1);
    await expect(
      f.service.resolveSession("req-before", session.tokens.accessToken),
    ).resolves.not.toBeNull();
    f.clock.advance(1);
    await expect(
      f.service.resolveSession("req-boundary", session.tokens.accessToken),
    ).resolves.toBeNull();
  });

  it("refreshes after access expiry while refresh remains valid", async () => {
    const f = createIdentityServiceFixture(new Date("2026-07-10T00:00:00Z"));
    const user = activeTeacher();
    f.users.add(user);
    f.passwords.register(user.passwordHash, "password");
    f.memberships.add(teacherMembership(user.id));
    const session = await f.service.login(user.loginIdentifier, "password");

    f.clock.advance(15 * 60 * 1000);
    await expect(
      f.service.refresh(session.tokens.refreshToken),
    ).resolves.toHaveProperty("activeSchoolId", "school-a");
  });

  it("rejects refresh at the refresh TTL boundary", async () => {
    const f = createIdentityServiceFixture(new Date("2026-07-10T00:00:00Z"));
    const user = activeTeacher();
    f.users.add(user);
    f.passwords.register(user.passwordHash, "password");
    f.memberships.add(teacherMembership(user.id));
    const session = await f.service.login(user.loginIdentifier, "password");

    f.clock.advance(7 * 24 * 60 * 60 * 1000);
    await expect(
      f.service.refresh(session.tokens.refreshToken),
    ).rejects.toHaveProperty("code", "AUTH_SESSION_EXPIRED");
  });

  it("rejects revoked sessions", async () => {
    const f = createIdentityServiceFixture();
    const user = activeTeacher();
    f.users.add(user);
    f.passwords.register(user.passwordHash, "password");
    f.memberships.add(teacherMembership(user.id));

    const session = await f.service.login(user.loginIdentifier, "password");
