import type { SubmissionStatus, SubmissionSummary } from "../../../../src/modules/submissions/domain/submission.types.js";
import type { SubmissionLookupPort } from "../../../../src/modules/submissions/ports/submission-lookup.port.js";

export class FakeSubmissionLookupRepository implements SubmissionLookupPort {
  private readonly summaries = new Map<string, SubmissionSummary>();

  add(...items: SubmissionSummary[]): void {
    for (const s of items) {
      this.summaries.set(s.id, s);
    }
  }

  async findSummaryById(schoolId: string, submissionId: string): Promise<SubmissionSummary | null> {
    const item = this.summaries.get(submissionId);
    if (!item || item.schoolId !== schoolId) return null;
    return item;
  }

  async transitionStatus(
    schoolId: string,
    submissionId: string,
    to: SubmissionStatus,
    _expectedRevision: number,
  ): Promise<SubmissionSummary> {
    const item = this.summaries.get(submissionId);
    if (!item || item.schoolId !== schoolId) {
      throw new Error("Not found");
    }
    const updated: SubmissionSummary = {
      ...item,
      status: to,
      revision: item.revision + 1,
      ...(to === "SUBMITTED" ? { submittedAt: new Date() } : {}),
    };
    this.summaries.set(submissionId, updated);
    return updated;
  }
}

import type {
  Submission,
  SubmissionSummary,
  CreateSubmissionInput,
  SubmissionStatus,
} from "../../../../src/modules/submissions/domain/submission.types.js";
import type {
  SubmissionRepositoryPort,
  ListSubmissionsOptions,
  PaginatedResult,
} from "../../../../src/modules/submissions/ports/submission-repository.port.js";

export class FakeSubmissionRepository implements SubmissionRepositoryPort {
  private readonly submissions = new Map<string, Submission>();
  private idCounter = 0;

  add(...items: Submission[]): void {
    for (const s of items) {
      this.submissions.set(s.id, s);
    }
  }

  async findById(schoolId: string, submissionId: string): Promise<Submission | null> {
    const item = this.submissions.get(submissionId);
    if (!item || item.schoolId !== schoolId) return null;
    return item;
  }

  async findByEnrollmentAndIdempotencyKey(
    enrollmentId: string,
    idempotencyKey: string,
  ): Promise<Submission | null> {
    for (const s of this.submissions.values()) {
      if (s.enrollmentId === enrollmentId && s.idempotencyKey === idempotencyKey) {
        return s;
      }
    }
    return null;
  }

  async listByAssignment(
    schoolId: string,
    assignmentId: string,
    options: ListSubmissionsOptions,
  ): Promise<PaginatedResult<SubmissionSummary>> {
    let all = Array.from(this.submissions.values()).filter(
      (s) => s.schoolId === schoolId && s.assignmentId === assignmentId,
    );
    if (options.status) {
      all = all.filter((s) => s.status === options.status);
    }
    if (options.enrollmentIds) {
      const allowed = new Set(options.enrollmentIds);
      all = all.filter((s) => allowed.has(s.enrollmentId));
    }
    const limit = options.limit;
    const start = options.cursor ? Number.parseInt(options.cursor, 10) : 0;
    const items = all.slice(start, start + limit).map(toSummary);
    const hasMore = all.length > start + limit;
    return { items, nextCursor: hasMore ? String(start + limit) : null, hasMore };
  }

  async listByEnrollment(
    schoolId: string,
    enrollmentId: string,
  ): Promise<readonly SubmissionSummary[]> {
    return Array.from(this.submissions.values())
      .filter((s) => s.schoolId === schoolId && s.enrollmentId === enrollmentId)
      .map(toSummary);
  }

  async save(input: CreateSubmissionInput): Promise<Submission> {
    const id = `submission-${++this.idCounter}`;
    const now = new Date();
    const attemptNo = await this.getNextAttemptNo(input.assignmentId, input.enrollmentId);
    const item: Submission = {
      id,
      schoolId: input.schoolId,
      assignmentId: input.assignmentId,
      enrollmentId: input.enrollmentId,
      attemptNo,
      status: "IN_PROGRESS",
      idempotencyKey: input.idempotencyKey,
      revision: 0,
      createdAt: now,
      updatedAt: now,
    };
    this.submissions.set(id, item);
    return item;
  }

  async updateStatus(
    schoolId: string,
    submissionId: string,
    status: SubmissionStatus,
    expectedRevision: number,
  ): Promise<Submission> {
    const existing = this.submissions.get(submissionId);
    if (!existing || existing.schoolId !== schoolId) {
      throw new Error("Not found");
    }
    if (existing.revision !== expectedRevision) {
      throw new Error("Conflict");
    }
    const updated: Submission = {
      ...existing,
      status,
      revision: existing.revision + 1,
      ...(status === "SUBMITTED" ? { submittedAt: new Date() } : {}),
      updatedAt: new Date(),
    };
    this.submissions.set(submissionId, updated);
    return updated;
  }

  async getNextAttemptNo(assignmentId: string, enrollmentId: string): Promise<number> {
    const existing = Array.from(this.submissions.values()).filter(
      (s) => s.assignmentId === assignmentId && s.enrollmentId === enrollmentId,
    );
    return existing.length + 1;
  }
}

function toSummary(s: Submission): SubmissionSummary {
  return {
    id: s.id,
    schoolId: s.schoolId,
    assignmentId: s.assignmentId,
    enrollmentId: s.enrollmentId,
    attemptNo: s.attemptNo,
    status: s.status,
    revision: s.revision,
    ...(s.submittedAt ? { submittedAt: s.submittedAt } : {}),
    createdAt: s.createdAt,
  };
}

import {
  ConsentStatus,
  PairingStatus,
  RiskLevel,
  TeacherReviewStatus,
} from "../../../../src/modules/support-pairings/domain/support-pairing.types.js";
import type {
  SupportPairing,
  SupportSession,
} from "../../../../src/modules/support-pairings/domain/support-pairing.types.js";
import type {
  ListPairingsOptions,
  PaginatedResult,
  SupportPairingRepositoryPort,
} from "../../../../src/modules/support-pairings/ports/support-pairing-repository.port.js";

export class FakeSupportPairingRepository implements SupportPairingRepositoryPort {
  private pairings: Map<string, SupportPairing> = new Map();
  private sessions: Map<string, SupportSession> = new Map();
  private nextPairingId = 1;
  private nextSessionId = 1;

  async findById(
    schoolId: string,
    pairingId: string,
  ): Promise<SupportPairing | null> {
    const p = this.pairings.get(pairingId);
    return p && p.schoolId === schoolId ? p : null;
  }

  async findBySchoolId(
    schoolId: string,
    options: ListPairingsOptions,
  ): Promise<PaginatedResult<SupportPairing>> {
    let items = [...this.pairings.values()].filter(
      (p) => p.schoolId === schoolId,
    );

    if (options.status) {
      items = items.filter((p) => p.status === options.status);
    }

    const limit = options.limit;
    const start = options.cursor
      ? items.findIndex((i) => i.id === options.cursor) + 1
      : 0;
    const slice = items.slice(start, start + limit);
    const hasMore = start + limit < items.length;

    return {
      items: slice,
      nextCursor:
        hasMore && slice.length > 0 ? slice[slice.length - 1].id : null,
      hasMore,
    };
  }

  async create(
    schoolId: string,
    data: Omit<
      SupportPairing,
      "id" | "consentStatus" | "status" | "createdAt" | "updatedAt"
    >,
  ): Promise<SupportPairing> {
    const now = new Date();
    const p: SupportPairing = {
      id: `pairing-${this.nextPairingId++}`,
      schoolId,
      studentUserId: data.studentUserId,
      volunteerUserId: data.volunteerUserId,
      supervisorTeacherId: data.supervisorTeacherId,
      consentStatus: ConsentStatus.PENDING,
      goal: data.goal,
      status: PairingStatus.PENDING_CONSENT,
      createdAt: now,
      updatedAt: now,
    };
    this.pairings.set(p.id, p);
    return p;
  }

  async updateConsentStatus(
    schoolId: string,
    pairingId: string,
    consentStatus: ConsentStatus,
  ): Promise<SupportPairing> {
    const p = this.pairings.get(pairingId);
    if (!p || p.schoolId !== schoolId) throw new Error("not found");
    const updated: SupportPairing = {
      ...p,
      consentStatus,
      updatedAt: new Date(),
    };
    this.pairings.set(pairingId, updated);
    return updated;
  }

  async updateStatus(
    schoolId: string,
    pairingId: string,
    status: PairingStatus,
  ): Promise<SupportPairing> {
    const p = this.pairings.get(pairingId);
    if (!p || p.schoolId !== schoolId) throw new Error("not found");
    const updated: SupportPairing = { ...p, status, updatedAt: new Date() };
    this.pairings.set(pairingId, updated);
    return updated;
  }

  async findSessionById(
    schoolId: string,
    sessionId: string,
  ): Promise<SupportSession | null> {
    const s = this.sessions.get(sessionId);
    if (!s) return null;
    const pairing = this.pairings.get(s.pairingId);
    return pairing && pairing.schoolId === schoolId ? s : null;
  }

  async listSessionsByPairing(
    schoolId: string,
    pairingId: string,
  ): Promise<readonly SupportSession[]> {
    const pairing = this.pairings.get(pairingId);
    if (!pairing || pairing.schoolId !== schoolId) return [];
    return [...this.sessions.values()].filter(
      (s) => s.pairingId === pairingId,
    );
  }

  async createSession(
    schoolId: string,
    _pairingId: string,
    data: Omit<
      SupportSession,
      "id" | "riskLevel" | "teacherReviewStatus" | "createdAt" | "updatedAt"
    >,
  ): Promise<SupportSession> {
    const now = new Date();
    const s: SupportSession = {
      id: `session-${this.nextSessionId++}`,
      pairingId: data.pairingId,
      scheduledAt: data.scheduledAt,
      summary: undefined,
      nextStep: undefined,
      riskLevel: RiskLevel.LOW,
      teacherReviewStatus: TeacherReviewStatus.PENDING,
      createdAt: now,
      updatedAt: now,
    };
    this.sessions.set(s.id, s);
    return s;
  }

  async updateSessionReviewStatus(
    _schoolId: string,
    sessionId: string,
    teacherReviewStatus: TeacherReviewStatus,
  ): Promise<SupportSession> {
    const s = this.sessions.get(sessionId);
    if (!s) throw new Error("session not found");
    const updated: SupportSession = {
      ...s,
      teacherReviewStatus,
      updatedAt: new Date(),
    };
    this.sessions.set(sessionId, updated);
    return updated;
  }

  /** Test helper: seed a pairing directly into the store */
  addPairing(p: SupportPairing): void {
    this.pairings.set(p.id, p);
  }

  /** Test helper: seed a session directly into the store */
  addSession(s: SupportSession): void {
    this.sessions.set(s.id, s);
  }
}

