    for (const m of memberships) {
      this.memberships.set(this.key(m.schoolId, m.userId), m);
    }
  }

  async findMembership(
    schoolId: string,
    userId: string,
  ): Promise<Membership | null> {
    return this.memberships.get(this.key(schoolId, userId)) ?? null;
  }

