    schoolId: string,
    options: ListMembersOptions,
  ): Promise<PaginatedResult<SchoolMember>> {
    let all = Array.from(this.memberships.values()).filter(
      (m) => m.schoolId === schoolId,
    );

    if (options.role) {
      all = all.filter((m) => m.role === options.role);
    }
